;
	jsr     _clear_vram_buffer
;
; oam_clear();
;
	jsr     _oam_clear
;
; set_prg_bank(5);
;
	lda     #$05
	jsr     _set_prg_bank
;
; temppointer = igloo_game_screen;
;
	lda     #<(_igloo_game_screen)
	ldx     #>(_igloo_game_screen)
	sta     _temppointer
	stx     _temppointer+1
;
; LZG_decode(temppointer, cmap);
;
	jsr     pushax
	lda     #<(_cmap)
	ldx     #>(_cmap)
	jsr     _LZG_decode
;
; vram_write(cmap, 32*32);
;
	lda     #<(_cmap)
	ldx     #>(_cmap)
	jsr     pushax
	ldx     #$04
	lda     #$00
	jsr     _vram_write
;
; memfill(cmap, 0, 32); // For character buffering later on when we want spaces
;
	jsr     decsp3
	lda     #<(_cmap)
	ldy     #$01
	sta     (sp),y
	iny
	lda     #>(_cmap)
	sta     (sp),y
	lda     #$00
	tay
	sta     (sp),y
	tax
	lda     #$20
	jsr     _memfill
;
; set_prg_bank(IGLOO_CODE_BANK);
;
	lda     #$01
	jsr     _set_prg_bank
;
; begin_igloo_sub();   
